const API_URL="https://app-70zj.onrender.com";async function login(){const cpf=document.getElementById("cpf").value;const mensagem=document.getElementById("mensagem");const cpfAdm=localStorage.getItem("cpfAdm");try{const res=await fetch(`${API_URL}/usuarios/${cpf}`);const result=await res.json();if(!result||result.erro){mensagem.textContent="CPF não encontrado.";mensagem.style.color="red";return}mensagem.textContent="Login realizado com sucesso!";mensagem.style.color="green";localStorage.setItem("cpf",cpf);window.location.href=cpf===cpfAdm?"adm.html":"home.html"}catch(error){console.error(error);mensagem.textContent="Erro ao conectar à API.";mensagem.style.color="red"}}window.addEventListener("load",()=>{const section=document.querySelector(".boletos");const cpf=localStorage.getItem("cpf");if(section&&cpf){fetch(`${API_URL}/boletos/${cpf}`).then(res=>{if(!res.ok)throw new Error("Erro ao carregar cobranças");return res.json()}).then(cobrancas=>{const lista=section.querySelector("ul");lista.innerHTML="";cobrancas.forEach(async cobranca=>{if(cobranca.pago)return;const li=document.createElement("li");li.innerHTML=`\n            <strong>${escapeHtml(cobranca.descricao)}</strong>: \n            Vencimento: ${escapeHtml(cobranca.vencimento)} - \n            Valor: R$ ${escapeHtml(cobranca.valor)}\n            <button>Gerar Pix</button>\n          `;const btn=li.querySelector("button");btn.addEventListener("click",async()=>{try{const params=new URLSearchParams({chave:"suachavepix@exemplo.com",valor:cobranca.valor,nome:"Associação",cidade:"Cidade XYZ"});const res=await fetch(`${API_URL}/pix?${params}`);const{qr:qr}=await res.json();window.open(qr,"_blank")}catch(err){alert("Erro ao gerar Pix.");console.error(err)}});lista.appendChild(li)});atualizarTotalPagar(cobrancas)}).catch(error=>{section.innerHTML="<p>Erro ao carregar cobranças.</p>";console.error(error)})}});function atualizarTotalPagar(cobrancas){const total=cobrancas.reduce((acc,c)=>{if(!c.pago){const valor=parseFloat(c.valor.replace(",","."))||0;return acc+valor}return acc},0);const totalEl=document.getElementById("total-pagar");if(totalEl){totalEl.textContent=`R$ ${total.toFixed(2).replace(".",",")}`}}function escapeHtml(str){return String(str).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}if("serviceWorker"in navigator){navigator.serviceWorker.register("/service-worker.js").then(reg=>console.log("Service Worker registrado:",reg)).catch(err=>console.error("Erro ao registrar o SW:",err))}